import { redirect } from "next/navigation";
import { headers } from "next/headers";
import { currentUser, impersonating } from "@/lib/auth";
import { safeNext } from "@/lib/safe-next";
import { db } from "@/lib/db";
import { getSetting, getSettingBool } from "@/lib/settings";
import { Shell as PortalShell, type NavSection } from "@/components/portal/Shell";
import { Shell } from "@/components/nx/Shell";
import { loadCreatorUserIds } from "@/lib/creator-accounts-data";
import { VerifyEmailBanner, ImpersonationBanner } from "@/components/nx/Banners";
import { UnverifiedEmailBanner } from "@/components/VerifyEmail";
import { isEmailVerified, isGrandfathered } from "@/lib/email-verification";
import { activeAnnouncementsForUser } from "@/lib/actions-broadcast";
import { AnnouncementBanner } from "@/components/customer/AnnouncementBanner";
import { PurchaseTracker } from "@/components/marketing/PurchaseTracker";
import { SignupTracker } from "@/components/marketing/SignupTracker";
import { PartnerSourceCapture } from "@/components/customer/PartnerSourceCapture";
import { HeardAboutUsPrompt } from "@/components/customer/HeardAboutUsPrompt";
import { CurrencyProvider } from "@/components/currency/CurrencyContext";
import { resolveDisplayCurrency } from "@/lib/currency-display";
import { PromoTrialPopup } from "@/components/marketing/PromoTrialPopup";

/** Hrefs hidden from the customer nav when their feature flag is off. */
const FEATURE_HREF: Record<string, string> = {
  "/dashboard/games": "feature_game_servers",
  "/dashboard/claude-code": "feature_claude_builder",
  "/dashboard/build": "feature_claude_builder",
  "/dashboard/domains": "feature_domains",
  "/dashboard/refer": "feature_referrals",
  "/dashboard/affiliate": "feature_referrals",
  // Hidden by default until each is fully live: the website builder's publish path
  // is dormant (ENABLE_REAL_PUBLISH), and calendar is not shipped. Flip the setting
  // to true to reveal — the routes/code stay intact, this only gates the nav entry.
  "/dashboard/sites": "feature_website_builder",
  "/dashboard/calendar": "feature_calendar",
};

const nav: NavSection[] = [
  {
    items: [{ label: "Dashboard", href: "/dashboard", icon: "home" }],
  },
  {
    label: "Compute",
    items: [
      { label: "Deploy", href: "/dashboard/deploy", icon: "rocket" },
      { label: "Servers", href: "/dashboard/servers", icon: "server" },
      { label: "Shared Hosting", href: "/dashboard/hosting", icon: "globe" },
      { label: "Game Servers", href: "/dashboard/games", icon: "server", tag: "FREE" },
      { label: "Server Directory", href: "/game-servers/directory", icon: "globe" },
      { label: "Volumes", href: "/dashboard/volumes", icon: "db" },
    ],
  },
  {
    label: "Build",
    items: [
      { label: "Build with AI", href: "/dashboard/claude-code", icon: "sparkle" },
      { label: "Matrix", href: "/dashboard/build", icon: "bolt" },
      // Kept in sync with lib/nx/nav.ts's own NxLabs entry — see that file's
      // comment on the two nav arrays this codebase currently carries.
      { label: "NxLabs", href: "/dashboard/nxlabs", icon: "server" },
    ],
  },
  {
    label: "Network",
    items: [
      { label: "Domains", href: "/dashboard/domains", icon: "globe" },
      { label: "Website builder", href: "/dashboard/sites", icon: "globe" },
      { label: "Calendar", href: "/dashboard/calendar", icon: "calendar" },
      { label: "SSL certificates", href: "/dashboard/ssl", icon: "shield" },
    ],
  },
  {
    // "Mail" groups the two easily-confused surfaces: Inbox is the actual webmail
    // reader (/dashboard/mail); Mailboxes is where you create and manage the email
    // accounts (/dashboard/email, formerly the ambiguous "Business email").
    label: "Mail",
    items: [
      { label: "Inbox", href: "/dashboard/mail", icon: "chat" },
      { label: "Mailboxes", href: "/dashboard/email", icon: "server" },
    ],
  },
  {
    label: "Tools",
    items: [
      { label: "Migration Center", href: "/dashboard/migrate", icon: "rocket" },
      { label: "Free tools", href: "/dashboard/tools", icon: "bolt" },
      { label: "What's New", href: "/dashboard/whats-new", icon: "sparkle" },
    ],
  },
  {
    label: "Account",
    items: [
      // Billing + Invoices merged (invoices live as a tab on the billing page);
      // Refer & earn + Affiliate merged; Support + Feedback merged.
      { label: "Billing", href: "/dashboard/billing", icon: "card" },
      { label: "Refer & earn", href: "/dashboard/refer", icon: "gift" },
      { label: "Partner Program", href: "/dashboard/partner", icon: "users" },
      { label: "Team", href: "/dashboard/team", icon: "users" },
      { label: "Support", href: "/dashboard/support", icon: "lifebuoy" },
      { label: "Activity", href: "/dashboard/activity", icon: "pulse" },
      { label: "Settings", href: "/dashboard/settings", icon: "cog" },
    ],
  },
];

/* viewport-fit=cover lets the portal's bottom tab bar and drawer pad themselves
   with env(safe-area-inset-*) on notched phones; only this subtree uses env(). */
export const viewport = { width: "device-width", initialScale: 1, viewportFit: "cover" } as const;

export default async function DashboardLayout({ children }: { children: React.ReactNode }) {
  const user = await currentUser();
  if (!user) {
    // Where they were actually headed — critically, a marketing "Deploy"
    // button's full query string (game/plan/addon selection, see
    // lib/deploy-intent.ts), not just the bare path. Without this, EVERY
    // logged-out visit to any /dashboard/* route lost its destination on this
    // redirect, silently dropping the selection a Deploy click had just
    // encoded. `x-pathname`/`x-search` come from middleware.ts (Server
    // Components can't read the current URL directly); `safeNext` is the
    // same single-slash-absolute-path allowlist every other `?next=`
    // producer already uses (lib/safe-next.ts), so this is never a second
    // validation rule to keep in sync.
    const h = await headers();
    const dest = safeNext(`${h.get("x-pathname") ?? "/dashboard"}${h.get("x-search") ?? ""}`);
    // mkt-011 (flag growth_guest_configurator, default off): a logged-out visitor to the
    // deploy wizard — which is where EVERY marketing "Deploy" button lands — gets the public
    // configurator with their selection carried in the same query, instead of a login wall.
    // They sign up at its Payment step and resume here.
    if (dest && (dest === "/dashboard/deploy" || dest.startsWith("/dashboard/deploy?")) && (await getSettingBool("growth_guest_configurator", false))) {
      redirect(dest.replace("/dashboard/deploy", "/configure"));
    }
    redirect(dest ? `/login?next=${encodeURIComponent(dest)}` : "/login");
  }
  const imp = await impersonating();

  // Maintenance mode: gate the whole customer portal for non-admins. Admins (and
  // admins impersonating a customer) always pass so they can keep working. This
  // only covers the dashboard tree — /login and /admin have their own layouts.
  if (user.role !== "ADMIN" && (await getSettingBool("maintenance_mode", false))) {
    const message = await getSetting("maintenance_message");
    return (
      <main
        style={{
          minHeight: "100vh",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: "1rem",
          padding: "2rem",
          textAlign: "center",
        }}
      >
        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Down for maintenance</h1>
        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>{message}</p>
      </main>
    );
  }

  // Hide nav entries whose feature flag is disabled (secondary to the server-side
  // refusals in the order/create actions).
  const flags: Record<string, boolean> = {
    feature_game_servers: await getSettingBool("feature_game_servers", true),
    feature_claude_builder: await getSettingBool("feature_claude_builder", true),
    feature_domains: await getSettingBool("feature_domains", true),
    feature_referrals: await getSettingBool("feature_referrals", true),
    // Off by default — hidden until publishing / the feature is live (see FEATURE_HREF).
    feature_website_builder: await getSettingBool("feature_website_builder", false),
    feature_calendar: await getSettingBool("feature_calendar", false),
  };
  const visibleNav: NavSection[] = nav
    .map((section) => ({
      ...section,
      items: section.items.filter((item) => {
        const flag = FEATURE_HREF[item.href];
        return !flag || flags[flag];
      }),
    }))
    .filter((section) => section.items.length > 0);

  const notifications = await db.notification.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
    take: 15,
  });

  // Support badge: this customer's own tickets awaiting a staff reply
  // (their newly opened tickets + threads where they replied last). Fails soft.
  const supportAwaiting = await db.ticket
    .count({ where: { userId: user.id, status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })
    .catch(() => 0);
  const navWithBadges: NavSection[] = visibleNav.map((section) => ({
    ...section,
    items: section.items.map((item) =>
      item.href === "/dashboard/support" && supportAwaiting > 0
        ? { ...item, badge: supportAwaiting }
        : item
    ),
  }));

  // Provide the display-currency context to the portal so browse/catalog prices
  // can localize. DISPLAY ONLY: wallet balances, invoices and any actual CHARGE
  // amount must stay in USD and are NOT routed through this — see the boundary
  // note in lib/currency.ts. Only components that explicitly opt in via
  // `useDisplayMoney()` convert; nothing here is auto-converted.
  const { currency: displayCurrency, rates: fxRates } = await resolveDisplayCurrency();

  return (
    <CurrencyProvider initialCurrency={displayCurrency} rates={fxRates}>
    {/* Rendered as a SIBLING before <Shell>, not passed as one of its
        children — Shell's own root (components/nx/Shell.tsx) renders its top
        navbar (search, currency, notifications, profile) ahead of whatever
        children it's given, so a child never sits above that bar no matter
        how early it's ordered among the other children. This is the same
        topmost slot SandboxBanner occupies in the root layout (above
        literally everything, app/layout.tsx) — moved out here (2026-09-22,
        real feedback) after it rendered below the email-verification banner
        AND below Shell's own top bar. */}
    {!imp && <PromoTrialPopup />}
    {/* Badges for the designed rail. `supportAwaiting` is already computed
        above for the portal shell's own nav; this reuses it rather than
        counting the same tickets a second time. */}
    {/* The Nexion shell, ported verbatim from the design sandbox. It takes the
        session user and nothing else — the nav is the designed twelve-item rail
        (lib/nx/nav.ts), not the portal's generated one.

        STILL TO PORT from components/portal/Shell: the notifications panel and
        the impersonation banner. Both are real features with no counterpart in
        the design yet; they are not lost, just not drawn here. Design them, then
        wire `notifications` / `impersonation` back in. */}
    {/* Marks <html> as the portal before first paint; the portal's CSS in
        app/globals.css is scoped to `:root.nx-portal` (see the note there).
        Shell keeps it in sync on client-side navigation. */}
    <script dangerouslySetInnerHTML={{ __html: "document.documentElement.classList.add('nx-portal')" }} />
    <Shell
      user={{ first: user.name.split(" ")[0], email: user.email, balanceCents: user.balanceCents, creator: (await loadCreatorUserIds([user.id])).has(user.id) }}
      badges={{ "/dashboard/support": supportAwaiting }}
      notifications={notifications.map((n) => ({
        id: n.id,
        title: n.title,
        body: n.body,
        href: n.href,
        readAt: n.readAt ? n.readAt.toISOString() : null,
        createdAt: n.createdAt.toISOString(),
      }))}
    >
      {/* Impersonation goes FIRST and is never dismissible — an admin who
          forgets which account they are in is the expensive failure here. */}
      {imp && <ImpersonationBanner adminName={imp.admin.name} targetEmail={imp.target.email} />}
      {/* Unverified accounts browse the whole portal freely; only buying is
          gated (lib/email-verification.ts). The prompt lives here rather than at
          checkout so the customer meets the prerequisite while it is cheap to
          fix, instead of meeting it with a card in their hand. Hidden while an
          admin is impersonating: it is not the admin's address to confirm, and
          the resend button would mail the customer from inside someone else's
          session. */}
      {!imp && !isEmailVerified(user) && !isGrandfathered(user) && (
        <VerifyEmailBanner email={user.email} />
      )}
      {/* Admin broadcasts — dismissible per-user. Soft-fails to nothing so a
          broadcast query problem can never take down the portal. */}
      <AnnouncementBanner announcements={await activeAnnouncementsForUser().catch(() => [])} />
      {/* Fires the Meta/Google Purchase conversion when a freshly-paid order lands on
          any dashboard route (fulfil-checkout tags the redirect). No-op otherwise. */}
      <PurchaseTracker />
      {/* Fires the "signup" conversion once when a freshly-registered account lands
          here (register() redirects to ?signup=1). Strips the marker; no-op otherwise. */}
      <SignupTracker />
      {/* Kodely (or any future partner) deep link (?ref=kodely) -> a short-lived
          cookie so payAndDeploy/purchaseDomain can attribute the order without
          threading the param through every wizard step. */}
      <PartnerSourceCapture />
      {/* One-time "How did you hear about us?" survey. Only when the account has
          not answered yet (heardAboutUs is null) and NOT while an admin is
          impersonating — the admin must never answer the survey on the
          customer's behalf. The server action is itself guarded to write only
          when null, so this is a UI gate over an idempotent write. */}
      {!imp && user.heardAboutUs == null && <HeardAboutUsPrompt />}
      {/* What's New lives in the topbar now (components/nx/whatsnew/WhatsNewLauncher.tsx,
          mounted by Shell): an unread dot plus the latest-release dialog, which
          opens by itself once per new release. */}
      {children}
    </Shell>
    </CurrencyProvider>
  );
}

import { createHash } from "node:crypto";
import { SignJWT, jwtVerify, type JWTPayload } from "jose";
import { cookies, headers } from "next/headers";
import { cache } from "react";
import { db } from "./db";
import { getSettingInt } from "./settings";
import { clientIp, UNKNOWN_IP } from "./rate-limit";
import { geoLocateIp } from "./geo-ip";
import type { User } from "@prisma/client";

const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
const COOKIE = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";

/** SHA-256 hex of a session token — the value stored in `UserSession.tokenHash`.
 *  Same reasoning as `ApiKey.keyHash` / `ApiToken.tokenHash`: never persist the
 *  bearer value itself, only a digest a stolen table can't be replayed with. */
function sessionTokenHash(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

/**
 * The CURRENT request's own UserSession.tokenHash, or null if there is no
 * session cookie. Settings' "Active sessions" list is titled "Every device
 * currently signed in", but its empty state says "No OTHER sessions are on
 * record" and its bulk action is "Sign out everywhere ELSE" — the list has
 * always meant OTHER devices, the same distinction `revokeSession`'s sibling
 * action already makes deliberately (see lib/nx/account.ts:revokeOtherSessions):
 * "signing yourself out of the page you are standing on is not what the
 * control means." Exported so the page that lists sessions can exclude this
 * one, the same way the row would otherwise offer a "Revoke" button that
 * instantly signs out the tab you clicked it from, unlabeled and with no
 * separate confirmation from "Sign out everywhere else".
 */
export async function currentSessionTokenHash(): Promise<string | null> {
  const jar = await cookies();
  const token = jar.get(COOKIE)?.value;
  return token ? sessionTokenHash(token) : null;
}

/**
 * Record (or refresh) the `UserSession` row for a session token, so "Active
 * sessions" in Settings shows something real and per-device revoke has a row
 * to act on. Best-effort and NEVER allowed to block or fail a sign-in — a geo
 * lookup or a write hiccup here must not be the reason a customer can't log in.
 */
async function trackSession(userId: string, token: string): Promise<void> {
  try {
    const h = await headers();
    const rawIp = clientIp(h);
    const ip = rawIp === UNKNOWN_IP ? null : rawIp;
    const userAgent = h.get("user-agent");
    const geo = geoLocateIp(ip);
    const location = geo ? [geo.city, geo.country].filter(Boolean).join(", ") || null : null;
    await db.userSession.create({
      data: { userId, tokenHash: sessionTokenHash(token), userAgent, ip, location },
    });
  } catch (e) {
    console.error("[auth] failed to record UserSession for", userId, e);
  }
}

export async function createSession(userId: string, opts?: { revokeOtherSessions?: boolean }) {
  // Session lifetime is admin-configurable (`session_length_days`, default 30).
  // Both the JWT expiry and the cookie maxAge use it so they stay in sync.
  const days = Math.max(1, await getSettingInt("session_length_days", 30));
  // Embed the account's current sessionVersion so a bump (password change/reset)
  // invalidates every previously-issued token. Missing => treated as 0.
  const acct = await db.user.findUnique({ where: { id: userId }, select: { sessionVersion: true } });
  // `typ` distinguishes this from the impersonation token below. Both are signed
  // with the SAME secret, so without it the two are interchangeable strings —
  // see the note on `assertSessionToken`.
  const token = await new SignJWT({ sub: userId, sv: acct?.sessionVersion ?? 0, typ: "session" })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime(`${days}d`)
    .sign(secret);
  const jar = await cookies();
  // Secure in production regardless of COOKIE_SECURE, matching the impersonation
  // cookie — a deploy that forgets COOKIE_SECURE=1 must not ship a non-Secure
  // session cookie. Local http dev stays non-secure (NODE_ENV !== "production").
  const secure = process.env.NODE_ENV === "production";
  jar.set(COOKIE, token, {
    httpOnly: true,
    sameSite: "lax",
    secure,
    maxAge: 60 * 60 * 24 * days,
    path: "/",
  });
  // Non-sensitive, JS-readable flag so the (static) marketing header can show
  // "Dashboard" instead of "Login/Get started" for a signed-in visitor. Carries
  // no identity — just presence. Always cleared alongside the session cookie.
  jar.set("nxeon_authed", "1", {
    httpOnly: false,
    sameSite: "lax",
    secure,
    maxAge: 60 * 60 * 24 * days,
    path: "/",
  });
  // `opts.revokeOtherSessions` mirrors the sessionVersion bump above at the
  // UserSession layer: changePassword and signOutOtherSessions both invalidate
  // every OTHER outstanding token via sessionVersion, then call createSession to
  // re-issue one for the caller's own device. Without this, the rows those older
  // tokens were tracked under (if any) would keep showing as "active" in
  // Settings even though sessionVersion has already made them unusable.
  if (opts?.revokeOtherSessions) {
    await db.userSession
      .updateMany({ where: { userId, revokedAt: null }, data: { revokedAt: new Date() } })
      .catch(() => {});
  }
  await trackSession(userId, token);
}

export async function destroySession() {
  const jar = await cookies();
  jar.delete(COOKIE);
  jar.delete("nxeon_authed");
}

/**
 * Is this payload allowed to act as a SESSION, as opposed to an impersonation
 * does check both. Do not reach for this function to authorise anything.
 */
export async function isSignedIn(): Promise<boolean> {
  const jar = await cookies();
  const token = jar.get(COOKIE)?.value;
  if (!token) return false;
  try {
    const { payload } = await jwtVerify(token, secret);
    return assertSessionToken(payload);
  } catch {
    return false;
  }
}

const IMP_COOKIE = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;

/** The real signed-in account, ignoring any impersonation. */
export const realUser = cache(async (): Promise<User | null> => {
  const jar = await cookies();
  const token = jar.get(COOKIE)?.value;
  if (!token) return null;
  try {
    const { payload } = await jwtVerify(token, secret);
    if (!payload.sub) return null;
    // An impersonation grant is not a session (see assertSessionToken).
    if (!assertSessionToken(payload)) return null;
    const user = await db.user.findUnique({ where: { id: payload.sub } });
    if (!user || user.suspended) return null;
    // Session revocation: a token is only valid while its embedded version matches
    // the account's current sessionVersion. Older tokens without `sv` count as 0,
    // so accounts that never bumped stay logged in (backward-compatible).
    const tokenVer = typeof payload.sv === "number" ? payload.sv : 0;
    if (tokenVer !== (user.sessionVersion ?? 0)) return null;
    // Per-device revocation: Settings' "Revoke" on one listed session sets that
    // ROW's revokedAt (lib/nx/account.ts:revokeSession) without touching
    // sessionVersion, so the check above alone would not see it. Look the token
    // up by its own hash and refuse it if that specific row says revoked.
    //
    // NO MATCHING ROW is treated as valid, deliberately — same call the codebase
    // already makes for tokens minted before `typ` existed (see the docblock on
    // `assertSessionToken`): a session from before this tracking existed, or from
    // a path that predates it, must not be mass-logged-out by a change that adds
    // bookkeeping. It simply isn't individually revocable until its owner logs in
    // again and gets a tracked row — the sessionVersion-based "sign out
    // everywhere" control above still reaches it regardless.
    const tokenHash = sessionTokenHash(token);
    const tracked = await db.userSession.findUnique({
      where: { tokenHash },
      select: { id: true, revokedAt: true, lastSeenAt: true },
    });
    if (tracked?.revokedAt) return null;
    if (tracked) {
      // Best-effort activity stamp — never block the request on this write, and
      // only bother once a minute per session rather than on every render.
      if (Date.now() - tracked.lastSeenAt.getTime() > 60_000) {
        db.userSession
          .update({ where: { id: tracked.id }, data: { lastSeenAt: new Date() } })
          .catch(() => {});
      }
    }
    return user;
  } catch {
    return null;
  }
});

/** Effective user: the impersonated customer if an admin is impersonating, else the real user. */
export const currentUser = cache(async (): Promise<User | null> => {
  const real = await realUser();
  if (!real) return null;
  if (real.role === "ADMIN") {
    const jar = await cookies();
    const imp = jar.get(IMP_COOKIE)?.value;
    if (imp) {
      try {
        const { payload } = await jwtVerify(imp, secret);
        if (payload.typ === "imp" && payload.adminId === real.id && typeof payload.sub === "string") {
          const target = await db.user.findUnique({ where: { id: payload.sub } });
          // The token outlives the checks `impersonateUser` made when it minted
          // it (2h), so they are re-made here against the CURRENT row rather
          // than trusted from the past:
          //
          //  - suspended: `realUser` refuses to hand out a session for a
          //    suspended account, and impersonation must not be a side door that
          //    resurrects one. Reviewing a suspended abuser's account is a
          //    read-only job; it must not come with the ability to act as them.
          //  - ADMIN: refused at mint time, but a customer promoted DURING an
          //    open impersonation would otherwise turn the impersonator's
          //    `currentUser()` into an ADMIN — and `requireAdmin` is built on
          //    `currentUser`, so admin actions would run attributed to the
          //    promoted account instead of the person taking them. The rule that
          //    admins refuse to act while impersonating depends on this.
          //
          // Falling through to the real admin is the safe failure: they are
          // simply themselves again, which is visible on screen.
          if (target && !target.suspended && target.role !== "ADMIN") return target;
        }
      } catch {
        /* expired/invalid impersonation — fall through to real user */
      }
    }
  }
  return real;
});

/** Non-null when the current request is an admin impersonating a customer. */
export const impersonating = cache(async (): Promise<{ admin: User; target: User } | null> => {
  const real = await realUser();
  if (!real || real.role !== "ADMIN") return null;
  const target = await currentUser();
  if (!target || target.id === real.id) return null;
  return { admin: real, target };
});

export async function setImpersonation(targetUserId: string) {
  const real = await realUser();
  if (!real || real.role !== "ADMIN") throw new Error("FORBIDDEN");
  // `typ: "imp"` marks this as a grant, never a session (see assertSessionToken).
  const token = await new SignJWT({ sub: targetUserId, adminId: real.id, typ: "imp" })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("2h")
    .sign(secret);
  const jar = await cookies();
  jar.set(IMP_COOKIE, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    maxAge: 7200,
  });
}

export async function clearImpersonation() {
  const jar = await cookies();
  jar.delete(IMP_COOKIE);
}

/**
 * Guard for wallet-debit / paid actions: refuse to run while an admin is
 * impersonating a customer. Keeps money movements attributable to the account
 * holder and prevents an admin from spending a customer's balance on their behalf.
 * Throws a friendly, user-facing error. Call at the top of every spend path.
 */
export async function assertNotImpersonating(): Promise<void> {
  const imp = await impersonating();
  if (imp) {
    throw new Error(
      "This action is disabled while impersonating a customer. Stop impersonating to continue.",
    );
  }
}

export async function requireUser(): Promise<User> {
  const user = await currentUser();
  if (!user) throw new Error("UNAUTHORIZED");
  return user;
}

export async function requireAdmin(): Promise<User> {
  const user = await requireUser();
  if (user.role !== "ADMIN") throw new Error("FORBIDDEN");
  return user;
}

/**
 * Require any staff role (SUPPORT / BILLING / ADMIN). Uses the real signed-in
 * account, ignoring impersonation. Throws FORBIDDEN for customers. Fine-grained
 * per-area gating lives in lib/rbac.ts (`requireArea`).
 */
export async function requireStaff(): Promise<User> {
  const user = await realUser();
  if (!user) throw new Error("UNAUTHORIZED");
  if (user.role !== "SUPPORT" && user.role !== "BILLING" && user.role !== "ADMIN") {
    throw new Error("FORBIDDEN");
  }
  return user;
}

