  const p = parseLabsParams(await searchParams);
  const filtered = isFiltered(p);

  const [fams, result, totalDl, servers, cats, loaders, featured, top, recent, rated] = await Promise.all([
    listFamilies(),
    runLabsQuery(p),
    totalDownloadsFor(),
    myModServers(user.id),
    categoryCounts(p.game),
    listLoaderCounts(p.game),
    filtered ? [] : listFeaturedMods(undefined, 12),
    filtered ? [] : listTopDownloadedMods(undefined, 12),
    filtered ? [] : listRecentlyUpdatedMods(undefined, 12),
    filtered ? [] : listTopRatedMods(undefined, 12),
  ]);
  const serverIds = servers.map((s) => s.id);
  const shown: ModSummary[] = [...result.mods, ...featured, ...top, ...recent, ...rated];
  const [state, installed] = await Promise.all([
    installStateFor(serverIds, Array.from(new Set(shown.map((m) => m.id)))),
    myInstalledMods(serverIds),
  ]);

  const totalMods = fams.reduce((s, f) => s + f.count, 0);
  const myFamilies = new Set(servers.map((s) => s.family));
  const live = installed.filter((r) => r.status === "INSTALLED" || r.status === "INSTALLING");
  const ctx = { servers, state, showGame: !p.game };
  const games = fams.map((f) => ({ ...f, poster: gameArt(f.family).poster }));
  // Your games first, then by catalogue size — the tiles you'll actually use lead.
  games.sort((a, b) => Number(myFamilies.has(b.family)) - Number(myFamilies.has(a.family)) || b.count - a.count);
