        <LabsRail label={title}>
          {mods.map((m) => <RailItem key={m.id}>{labsCard(m, { ...ctx, showGame: true })}</RailItem>)}
        </LabsRail>
      </section>
    );

  return (
    <div className="nxl-root mx-auto flex w-full max-w-[1520px] flex-col gap-8">
      <LabsNavProvider>
        {/* ── hero ─────────────────────────────────────────────────────── */}
        <header className={"nxl-hero nx-dark-island " + (filtered ? "px-5 py-6 sm:px-8" : "px-5 py-9 sm:px-10 sm:py-12")}>
          <div className="nxl-hero-bg" aria-hidden>
            {/* eslint-disable-next-line @next/next/no-img-element -- static hero art; fetchPriority high, it's the LCP */}
            <img src="/nxlabs/hero-collage.webp" alt="" fetchPriority="high" decoding="async" />
          </div>
          <div className={"flex flex-col gap-5 " + (filtered ? "" : "items-center text-center")}>
            {!filtered && <LabsLogo />}
            <div className={"flex flex-col gap-2 " + (filtered ? "" : "items-center")}>
              <p className="nxl-eyebrow">{filtered ? "NxLabs" : "Mods fuel better games"}</p>
              <h1 className={"font-extrabold leading-[1.04] tracking-[-0.035em] " + (filtered ? "text-[26px] sm:text-[30px]" : "text-[32px] sm:text-[46px]")}>
                {filtered ? "Search the catalogue" : <>Every mod worth running.<br /><span className="nxl-grad-text">Verified at the source.</span></>}
              </h1>
              {!filtered && (
                <p className="max-w-[62ch] text-[14px] leading-[1.55] text-[#b9c8ea]">
                  {totalMods.toLocaleString("en-US")} mods, plugins and add-ons for {fams.length} games — real download counts, real licences, and one-tap
                  install onto {servers.length ? "the servers you run" : "an Nxeon server"}.
                </p>
              )}
            </div>
            <form method="get" action={`${BASE}#browse`} role="search" className="nxl-hsearch">
              <Icon name="search" size={15} tone="inherit" className="flex-none text-[#8ea3d6]" />
              <input
                type="search" name="q" defaultValue={p.q} maxLength={100} autoComplete="off" enterKeyHint="search"
                placeholder={`Search ${totalMods.toLocaleString("en-US")} mods and plugins`} aria-label="Search mods and plugins"
