                <option value="">All games</option>
                {fams.map((f) => <option key={f.family} value={f.family}>{f.label}</option>)}
              </select>
              <button type="submit" className="nxl-gobtn">Search <span aria-hidden>→</span></button>
            </form>
            {!filtered && (
              <>
                <div className="flex flex-wrap items-center justify-center gap-2">
                  <span className="text-[12px] text-[#93aede]">Popular:</span>
                  {popular.map((g) => (
                    <Link key={g.family} href={`${BASE}/games/${g.family}`} className="nxl-hchip" prefetch={false}>{g.label}</Link>
                  ))}
                </div>
                <div className="mt-1 flex flex-wrap justify-center gap-x-10 gap-y-4">
                  <span className="nxl-stat"><b className="num">{totalMods.toLocaleString("en-US")}</b><span>mods &amp; plugins</span></span>
                  <span className="nxl-stat"><b className="num">{fams.length}</b><span>games</span></span>
                  {totalDl > 0 && <span className="nxl-stat"><b className="num">{formatDownloads(totalDl)}</b><span>downloads at the source</span></span>}
                  {live.length > 0 && <span className="nxl-stat"><b className="num">{live.length}</b><span>on your servers</span></span>}
                </div>
              </>
            )}
          </div>
        </header>

        <LabsTabs active={filtered ? "browse" : "discover"} installedCount={live.length} />

        {!filtered && (
          <>
            {installed.length > 0 && (
              <section>
                <LabsHead eyebrow="Your servers" title="Installed on your servers" href={`${BASE}/installed`} hrefLabel="Manage" />
                <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
                  {servers.filter((s) => installed.some((r) => r.serverId === s.id)).map((s) => {
                    const mine = installed.filter((r) => r.serverId === s.id);
                    const failed = mine.filter((r) => r.status === "FAILED").length;
                    const busy = mine.filter((r) => r.status === "INSTALLING" || r.status === "REMOVING").length;
                    return (
                      <Link key={s.id} href={`/dashboard/servers/${s.id}?tab=mods`} className="nxl-panel flex items-center gap-3 !p-4 transition-colors hover:border-[var(--color-rim-hi)]" prefetch={false}>
                        <span className="nxl-srv-dot" data-status={s.status} aria-hidden />
                        <span className="min-w-0 flex-1">
                          <span className="block truncate text-[14px] font-bold text-white">{s.name}</span>
                          <span className="block text-[12px] text-tx-faint">
                            {fams.find((f) => f.family === s.family)?.label ?? s.family} · {mine.length - failed} mod{mine.length - failed === 1 ? "" : "s"}
                            {busy > 0 && ` · ${busy} in progress`}
                          </span>
                        </span>
                        {failed > 0 && <span className="nxl-badge is-bad">{failed} failed</span>}
                        <span aria-hidden className="text-tx-faint">→</span>
                      </Link>
                    );
                  })}
                </div>
              </section>
            )}

            {rail("Featured mods", "Editor's picks", "Marked featured in the NxLabs catalogue.", featured, `${BASE}#browse`, "featured")}

            <section>
              <LabsHead eyebrow="Pick your game" title="Browse by game" sub={`${fams.length} games, each with its own featured picks, categories and filters.`} />
              <LabsGameTiles games={games} hrefFor={(f) => `${BASE}/games/${f}`} mine={myFamilies} />
            </section>

            {cats.length > 0 && (
              <section>
                <LabsHead eyebrow="Collections" title="Browse by what you need" sub="Every mod sorted into one clear category from its real source data." />
                <LabsCategoryTiles cats={cats} hrefFor={(k) => `${BASE}?cat=${k}#browse`} />
              </section>
            )}

            {rail("Most downloaded", "Real downloads, real ranking", "Ranked by real download counts from each mod's own source.", top, `${BASE}?sort=downloads#browse`, "top-downloaded")}
            {rail("Recently updated", "Straight from the source", "Ordered by each mod's real last release upstream.", recent, `${BASE}?sort=updated#browse`, "recently-updated")}
            {rail("Top rated", "Community favourites", "Rated by Nxeon customers — ranked by downloads until a mod has enough ratings of its own.", rated, `${BASE}?sort=rating#browse`, "top-rated")}
          </>
        )}

        {/* ── the catalogue ───────────────────────────────────────────── */}
        <section id="browse" className="scroll-mt-24">
          {!filtered && <LabsHead eyebrow="Everything" title="Browse the full catalogue" />}
          <LabsToolbar
            base={BASE}
            state={{ q: p.q, sort: p.sort, cat: p.cat, loader: p.loader, version: p.version, game: p.game, category: p.category }}
            sorts={LABS_SORTS}
            games={fams.map((f) => ({ value: f.family, label: f.label, count: f.count }))}
            cats={cats.map((c) => ({ value: c.cat.key, label: c.cat.label, count: c.count }))}
            loaders={loaders.map((l) => ({ value: l.loader, label: loaderLabel(l.loader), count: l.count }))}
            total={result.total}
          />
          <LabsPending className="mt-4">
            {result.mods.length > 0 ? (
              <>
                <LabsGrid>{result.mods.map((m, i) => labsCard(m, { ...ctx, priority: filtered && i < 4 }))}</LabsGrid>
                <LabsPager page={result.page} totalPages={result.totalPages} total={result.total} perPage={result.perPage || PER_PAGE}
                           hrefFor={(n) => labsHref(BASE, p, { page: n })} />
              </>
            ) : (
              <LabsEmpty
                title={p.q ? `Nothing matches “${p.q}”` : "No mods match these filters"}
                body={`Try a broader search${p.cat ? `, a different category than ${catLabel(p.cat)}` : ""}${p.loader ? " or any loader" : ""}. Names, categories and descriptions are all searched.`}
                action={<Link href={`${BASE}#browse`} className="btn-secondary">Clear filters</Link>}
              />
            )}
          </LabsPending>
        </section>
      </LabsNavProvider>
    </div>
  );
}
