import { Client, type SFTPWrapper } from "ssh2";
import { connectionTarget, serverManagementKey, serverRootPassword } from "../lib/sftp";
import { isSafeAbs, shq } from "../lib/mods/paths";
import type { GuestFs, GuestStat } from "../lib/mods/guest-fs";

type ServerLike = Parameters<typeof connectionTarget>[0] & { rootPassword: string | null; rootPasswordEnc?: string | null; sshManagementKeyEnc?: string | null };

const CONNECT_TIMEOUT_MS = 15_000;
const EXEC_TIMEOUT_MS = 120_000;

function need(p: string) {
  if (!isSafeAbs(p)) throw new Error(`unsafe guest path: ${p}`);
  return p;
}

export class SshGuestFs implements GuestFs {
  readonly kind = "ssh" as const;
  private conn: Client | null = null;
  private sftp: SFTPWrapper | null = null;

  private constructor() {}

  static async open(server: ServerLike): Promise<SshGuestFs> {
    const t = connectionTarget(server);
    if (!t) throw new Error("The server isn't reachable yet (no connection details).");
    const key = serverManagementKey(server);
    const pw = serverRootPassword(server);
    if (!key && !pw) throw new Error("The server has no SSH credentials on file.");
    const g = new SshGuestFs();
    const attempt = (auth: { privateKey: string } | { password: string }) =>
      new Promise<Client>((resolve, reject) => {
        const c = new Client();
        c.once("ready", () => resolve(c));
        c.once("error", (e) => reject(e));
        c.connect({ host: t.host, port: t.port, username: "root", readyTimeout: CONNECT_TIMEOUT_MS, ...auth });
      });
    let conn: Client | null = null;
    if (key) conn = await attempt({ privateKey: key }).catch((e) => { if (!pw) throw e; return null; });
    if (!conn) conn = await attempt({ password: pw! });
    g.conn = conn;
    g.sftp = await new Promise<SFTPWrapper>((res, rej) => conn!.sftp((e, s) => (e ? rej(e) : res(s))));
    return g;
  }

  close() {
    try { this.conn?.end(); } catch { /* best-effort */ }
    this.conn = null;
    this.sftp = null;
  }

  private exec(cmd: string): Promise<{ code: number; out: string }> {
    const c = this.conn;
    if (!c) return Promise.reject(new Error("SSH connection closed"));
    return new Promise((resolve, reject) => {
      c.exec(cmd, (err, stream) => {
        if (err) return reject(err);
        let out = "";
        const timer = setTimeout(() => { try { stream.close(); } catch { /* ignore */ } }, EXEC_TIMEOUT_MS);
        stream.on("data", (d: Buffer) => { if (out.length < 65536) out += d.toString("utf8"); });
        stream.stderr.on("data", (d: Buffer) => { if (out.length < 65536) out += d.toString("utf8"); });
        stream.on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, out }); });
      });
    });
  }

  private async sh(cmd: string, what: string) {
    const r = await this.exec(cmd);
    if (r.code !== 0) throw new Error(`${what} failed on the server: ${r.out.trim().slice(0, 200)}`);
  }

  stat(p: string): Promise<GuestStat | null> {
    need(p);
    return new Promise((resolve) => {
      this.sftp!.lstat(p, (err, s) => {
        if (err || !s) return resolve(null);
        if (s.isSymbolicLink()) return resolve(null);
        resolve({ type: s.isDirectory() ? "dir" : "file", size: s.size });
      });
    });
  }

  async readFile(p: string, maxBytes = 64 * 1024 * 1024): Promise<Buffer | null> {
    const st = await this.stat(p);
    if (!st || st.type !== "file" || st.size > maxBytes) return null;
    return new Promise((resolve) => this.sftp!.readFile(p, (err, data) => resolve(err ? null : (data as Buffer))));
  }

  async writeFile(p: string, data: Buffer): Promise<void> {
    need(p);
    await this.mkdirp(p.split("/").slice(0, -1).join("/") || "/");
    await new Promise<void>((resolve, reject) => this.sftp!.writeFile(p, data, (err) => (err ? reject(err) : resolve())));
  }

  async mkdirp(p: string): Promise<void> {
    await this.sh(`mkdir -p -- ${shq(need(p))}`, "creating a folder");
  }

  async rename(from: string, to: string): Promise<void> {
    need(from);
    need(to);
    await this.sh(`mkdir -p -- ${shq(to.split("/").slice(0, -1).join("/"))} && mv -f -T -- ${shq(from)} ${shq(to)}`, "moving a file");
  }

  async remove(p: string): Promise<void> {
    need(p);
    // Never anything shallower than /x/y — every path we manage is deeper.
    if (p.split("/").filter(Boolean).length < 2) throw new Error(`refusing to delete ${p}`);
    await this.sh(`rm -rf -- ${shq(p)}`, "removing a file");
  }

  list(dir: string): Promise<string[]> {
    need(dir);
    return new Promise((resolve) => this.sftp!.readdir(dir, (err, list) => resolve(err ? [] : list.map((e) => e.filename))));
  }

  async chownLike(ref: string, paths: string[]): Promise<void> {
    need(ref);
    const ps = paths.filter((p) => isSafeAbs(p));
    if (!ps.length) return;
    // Game containers run as their own user (steam, 1000, 845…); files written
    // over SFTP as root would otherwise be unreadable/unwritable to the game.
    await this.exec(`chown -R --reference=${shq(ref)} -- ${ps.map(shq).join(" ")} 2>/dev/null; true`);
  }

  async copy(from: string, to: string): Promise<void> {
    need(from);
    need(to);
    await this.sh(`mkdir -p -- ${shq(to.split("/").slice(0, -1).join("/"))} && cp -f -p -- ${shq(from)} ${shq(to)}`, "backing up a file");
  }
}
