const JAR_LIMITS = { maxEntries: 60_000, maxEntryBytes: 256 * 1024 * 1024, maxTotalBytes: 1024 * 1024 * 1024, maxRatio: 1000 };

/**
 * Jars and datapack zips are placed AS ONE FILE — we never extract them, so
 * their internal names (Java's `Outer$Inner.class`, `META-INF/versions/9/…`)
 * never touch the filesystem. They still have to BE what they claim: a real
 * ZIP container (an HTML error page or an installer .exe is refused), and a
 * datapack must carry a pack.mcmeta.
 */
export function placeJarOrDatapack(pkg: ResolvedPackage, bytes: Buffer, layout: Layout): PlacedFile[] | { error: string } {
  if (pkg.placement === "datapack") {
    const name = safeFileName(pkg.file.filename, [".zip"]);
    if (!name) return { error: `${pkg.name}'s file isn't a datapack .zip.` };
    let names: string[];
    try { names = zipEntryNames(bytes, JAR_LIMITS); } catch (e) { return { error: `${pkg.name}'s datapack is not a valid zip: ${(e as Error).message}` }; }
    if (!names.some((n) => /^([^/]+\/)?pack\.mcmeta$/.test(n))) return { error: `${pkg.name}'s zip has no pack.mcmeta — not a datapack.` };
    return [{ path: joinUnder(layout.dirs.datapacks, name), data: bytes }];
  }
  const name = safeFileName(pkg.file.filename, [".jar"]);
  if (!name) return { error: `${pkg.name}'s download isn't a .jar file — refused.` };
  let names: string[];
  try {
    names = zipEntryNames(bytes, JAR_LIMITS);
  } catch (e) {
    return { error: `${pkg.name}'s download isn't a valid jar (${e instanceof ArchiveError ? e.message : "unreadable"}) — refused.` };
  }
  if (pkg.placement === "plugin-jar" && !names.some((n) => /^(plugin|paper-plugin|bungee)\.yml$/.test(n))) {
    return { error: `${pkg.name}'s jar has no plugin.yml — it isn't a Bukkit/Paper plugin.` };
  }
  if (pkg.placement === "mod-jar" && !names.some((n) => /^(fabric\.mod\.json|quilt\.mod\.json|META-INF\/mods\.toml|META-INF\/neoforge\.mods\.toml|mcmod\.info)$/.test(n))) {
    return { error: `${pkg.name}'s jar has no Fabric/Quilt/Forge mod manifest — it isn't a server mod.` };
  }
  const dir = pkg.placement === "plugin-jar" ? layout.dirs.plugins : layout.dirs.mods;
  return [{ path: joinUnder(dir, name), data: bytes }];
}

