  pinnedVersion: string | null;
  config: Record<string, unknown> | null;
};

export type Layout = {
  /** Directory everything for this game lives under; ownership reference. */
  base: string;
  /** Named target directories (plugins, mods, datapacks, …). */
  dirs: Record<string, string>;
  /** The game version the server really runs, when it can be read. */
  gameVersion: string | null;
  /** Loader/flavour actually present (e.g. "oxide" vs "carbon"). */
  flavour?: string | null;
};

export type EngineDeps = {
  fs: GuestFs;
  fetcher: Fetcher;
  mirror?: MirrorLookup | null;
  now?: () => Date;
  /** Progress callback (job step text + percent). */
  progress?: (step: string, pct: number) => void | Promise<void>;
};

async function download(pkg: ResolvedPackage, deps: EngineDeps): Promise<{ bytes: Buffer; from: "mirror" | "upstream" | "prefetched" }> {
  if (pkg.prefetched) return { bytes: pkg.prefetched, from: "prefetched" };
  if (deps.mirror) {
    const hit = await deps.mirror(pkg.file);
    if (hit) return { bytes: hit, from: "mirror" };
  }
  if (pkg.file.size != null && pkg.file.size > MAX_FILE_BYTES) {
    throw new FetchError(`${pkg.name} is ${Math.round(pkg.file.size / 1048576)} MB — over the ${MAX_FILE_BYTES / 1048576} MB one-click limit`, "size");
  }
  const r = await deps.fetcher(pkg.file.url, {
    maxBytes: MAX_FILE_BYTES,
    timeoutMs: 180_000,
    expect: pkg.file.hashes,
    headers: pkg.file.headers,
  });
  return { bytes: r.bytes, from: "upstream" };
}

async function detectOrFail(installer: FamilyInstaller, fs: GuestFs, server: ServerFacts, mod: CatalogFacts | null): Promise<Layout> {
  const det = await installer.detect(fs, server, mod);
  if ("error" in det) throw new UserFacing(det.error);
  return det;
}

/** An error whose message is safe and meant for the customer. */
export class UserFacing extends Error {}

function failure(e: unknown): { ok: false; error: string } {
  if (e instanceof UserFacing) return { ok: false, error: e.message };
  if (e instanceof FetchError) return { ok: false, error: `Download refused: ${e.message}.` };
  const m = e instanceof Error ? e.message : String(e);
  return { ok: false, error: m.length > 300 ? m.slice(0, 300) + "…" : m };
}

async function pruneBackups(fs: GuestFs) {
  const names = (await fs.list(BACKUP_DIR)).filter((n) => /^\d{4}-/.test(n)).sort();
  for (const n of names.slice(0, Math.max(0, names.length - KEEP_BACKUPS))) await fs.remove(`${BACKUP_DIR}/${n}`);
}

/** Copy `paths` (those that exist) into a fresh backup folder. Returns path→backup copy. */
async function backup(fs: GuestFs, label: string, paths: string[], now: Date): Promise<Map<string, string>> {
  const out = new Map<string, string>();
  if (paths.length === 0) return out;
  const dir = `${BACKUP_DIR}/${stamp(now)}-${safeKey(label)}`;
  for (const p of paths) {
    const st = await fs.stat(p);
    if (!st || st.type !== "file") continue;
    const dest = `${dir}${p}`;
    await fs.copy(p, dest);
    out.set(p, dest);
  }
  if (await fs.stat(STATE_PATH)) await fs.copy(STATE_PATH, `${dir}/state.json`);
  await pruneBackups(fs);
  return out;
}

