/**
 * Load the server if (and only if) the caller owns it (or is an admin). Returns
 * the exact fields lib/sftp needs to open a connection. Throws generic errors
 * that the wrappers translate to typed results.
 */
async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      userId: true,
      status: true,
      rootPassword: true,
      rootPasswordEnc: true, sshManagementKeyEnc: true,
      sshPort: true,
      guestSshPort: true,
      dedicatedIp: { select: { address: true } },
      node: { select: { publicIp: true } },
    },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

/** Per-user throttle. Returns an error string when the caller should back off. */
function throttle(userId: string, op: string, max: number): string | null {
  const rl = checkRateLimit(`files:${op}:${userId}`, { max, windowMs: 60_000 });
  if (!rl.ok) return `Too many requests — slow down and retry in ${rl.retryAfterSec}s.`;
  return null;
}

function toMode(mode: number | null): string | null {
  return mode == null ? null : (mode & 0o777).toString(8).padStart(3, "0");
}

function entryOut(e: SftpEntry): FileEntry {
  return {
    name: e.name,
    isDirectory: e.isDirectory,
    size: e.size,
    modifiedMs: e.modifiedMs,
    mode: toMode(e.mode),
  };
}

/** Map an internal error to a safe, user-facing message. */
function safeError(err: unknown): string {
  const msg = err instanceof Error ? err.message : String(err);
  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
  // Path/traversal/size messages from lib/sftp are already user-safe.
  if (
    /traversal|absolute|too long|too large|Invalid|No such|Not a (file|directory)|already exists|reachable|root password|is a directory/i.test(
      msg
    )
  ) {
    return msg;
  }
  // Anything else (connection/protocol errors) — keep it generic.
  return "Could not reach the server's filesystem. Please try again shortly.";
}

// ---------------------------------------------------------------------------

 * UPLOAD_DIR + a `validateName`d basename — a path-traversal write is
 * structurally impossible. Size is capped both before and after base64 decode.
 *
 * `base64` accepts either a raw base64 string or a `data:...;base64,<payload>`
 * data URL (the shape a browser FileReader / paste produces).
 */
export async function uploadToServer(
  serverId: string,
  filename: string,
  base64: string
): Promise<{ ok: true; path: string; name: string } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "upload", 30);
    if (limited) return { ok: false, error: limited };

    if (typeof base64 !== "string" || base64.length === 0) {
      return { ok: false, error: "No file data was provided." };
    }
    // Accept a data: URL payload OR a bare base64 string.
    const comma = base64.indexOf(",");
    const payload = base64.startsWith("data:") && comma !== -1 ? base64.slice(comma + 1) : base64;
    // Cheap size guard BEFORE decoding: base64 inflates bytes by ~4/3.
    if (payload.length > Math.ceil((MAX_UPLOAD_BYTES * 4) / 3) + 8) {
      return { ok: false, error: "File exceeds the 15 MB upload limit." };
    }

    const buffer = Buffer.from(payload, "base64");
    if (buffer.length === 0) return { ok: false, error: "The file is empty or could not be decoded." };
    if (!Number.isFinite(buffer.length) || buffer.length > MAX_UPLOAD_BYTES) {
      return { ok: false, error: "File exceeds the 15 MB upload limit." };
    }

    const name = sanitizeUploadName(filename);
    const remotePath = joinPath(UPLOAD_DIR, name);

    // Ensure the uploads dir exists (best-effort: a pre-existing dir is fine;
    // the write below is the authoritative op and surfaces any real failure).
    try {
      await mkdirPath(server, UPLOAD_DIR);
    } catch {
      /* already exists / benign — the write will fail loudly if not */
    }
    await writeFileBuffer(server, remotePath, buffer);
    return { ok: true, path: remotePath, name };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

