 * server on a non-primary node means dialing the WRONG physical host
 * entirely, not just a wrong port — verified live 2026-09-05 as the root
 * cause of an entire class of "control panel dead for node-2" bugs.
 */
export function connectionTarget(server: SftpServer): { host: string; port: number } | null {
  const dedicated = !!server.dedicatedIp;
  const host = dedicated ? server.dedicatedIp!.address : (server.node?.publicIp ?? process.env.PUBLIC_IP ?? "");
  const port = dedicated ? (server.guestSshPort ?? 22) : server.sshPort;
  if (!host || !port) return null;
  return { host, port };
}

/**
 * Open one SFTP connection: the per-server management key first, falling back to the root
 * password (see the long note on Server.sshManagementKeyEnc). A fresh client per attempt:
 * reusing one after a failed connect is not a state ssh2-sftp-client guarantees to recover from.
 */
async function connectSftp(
  target: { host: string; port: number },
  privateKey: string | null,
  password: string | null
): Promise<SftpClient> {
  if (privateKey) {
    const keyClient = new SftpClient();
    try {
      await keyClient.connect({
        host: target.host,
        port: target.port,
        username: "root",
        privateKey,
        readyTimeout: CONNECT_TIMEOUT_MS,
      });
      return keyClient;
    } catch (e) {
      try { await keyClient.end(); } catch { /* best effort */ }
      if (!password) throw e;
    }
  }
  const client = new SftpClient();
  try {
    await client.connect({
      host: target.host,
      port: target.port,
      username: "root",
      password: password!,
      readyTimeout: CONNECT_TIMEOUT_MS,
    });
    return client;
  } catch (e) {
    try { await client.end(); } catch { /* best effort */ }
    throw e;
  }
}

/** Idle-expiring pool for READ operations (list/read); see lib/sftp-pool.ts for the security model. */
const globalForPool = globalThis as unknown as { __nxeonSftpPool?: ConnPool<SftpClient> };
const sftpPool: ConnPool<SftpClient> =
  globalForPool.__nxeonSftpPool ??
  (globalForPool.__nxeonSftpPool = new ConnPool<SftpClient>({
    idleMs: 25_000,
    maxEntries: 32,
    close: async (c) => { await c.end(); },
  }));

/** Short non-reversible fingerprint of the credential, so a rotated password/key abandons the pooled connection. */
function credFingerprint(privateKey: string | null, password: string | null): string {
  return createHash("sha256").update(`${privateKey ?? ""}\u0000${password ?? ""}`).digest("hex").slice(0, 16);
}

/**
 * Open an SFTP connection, run `fn(client)`, and close it (finally) — OR, when `opts.poolKey` is
 * given, run on a short-lived pooled connection instead. `poolKey` MUST be derived from the
 * authenticated user id and the server id by the caller (lib/actions-files.ts does
 * `${user.id}:${server.id}`) AFTER the ownership check; it is combined here with the target and a
 * credential fingerprint. Only use it for read operations.
 * In SANDBOX mode this is bypassed entirely — callers below short-circuit to
 * the in-memory filesystem before ever reaching here.
 */
export async function withSftp<T>(
  server: SftpServer,
  fn: (client: SftpClient) => Promise<T>,
  opts?: { poolKey?: string }
): Promise<T> {
  if (SANDBOX) {
    throw new Error("withSftp must not be called in sandbox mode");
  }
  const target = connectionTarget(server);
  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
  const privateKey = serverManagementKey(server);
  const password = serverRootPassword(server);
  if (!privateKey && !password) throw new Error("Server has no root password set.");

  if (opts?.poolKey) {
    const key = `${opts.poolKey}|${target.host}:${target.port}|${credFingerprint(privateKey, password)}`;
    return sftpPool.run(
      key,
    await client.mkdir(path, false);
  });
}

export async function renamePath(
  server: SftpServer,
  from: string,
  to: string
): Promise<void> {
  if (SANDBOX) {
    const src = simResolve(server.id, from);
    if (!src) throw new Error("No such file or directory.");
    const dst = simParent(server.id, to);
    if (!dst) throw new Error("Invalid destination.");
    if (dst.parent.children[dst.name]) {
      throw new Error("A file or folder with that name already exists.");
    }
    const srcLoc = simParent(server.id, from);
    if (!srcLoc) throw new Error("Cannot rename the root.");
    delete srcLoc.parent.children[srcLoc.name];
    dst.parent.children[dst.name] = { ...src, mtime: Date.now() };
    return;
  }

  await withSftp(server, async (client) => {
    await client.rename(from, to);
  });
}

