// ----------------------------------------------------------------------------
// Streaming helpers for the upload/download route
// ----------------------------------------------------------------------------

/** Read an entire file into a Buffer (used by the download endpoint). */
export async function readFileBuffer(server: SftpServer, path: string): Promise<Buffer> {
  if (SANDBOX) {
    const node = simResolve(server.id, path);
    if (!node) throw new Error("No such file.");
    if (node.type !== "file") throw new Error("Not a file.");
    return Buffer.from(node.content, "utf8");
  }

  return withSftp(server, async (client) => {
    const s = await client.stat(path);
    if (s.isDirectory) throw new Error("Not a file.");
    return (await client.get(path)) as Buffer;
  });
}

/** Write a Buffer to a path (used by the upload endpoint). */
export async function writeFileBuffer(
  server: SftpServer,
  path: string,
  data: Buffer
): Promise<void> {
  if (SANDBOX) {
    const loc = simParent(server.id, path);
    if (!loc) throw new Error("Invalid path.");
    const existing = loc.parent.children[loc.name];
    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
    loc.parent.children[loc.name] = {
      type: "file",
      mtime: Date.now(),
      mode: existing?.type === "file" ? existing.mode : 0o644,
      content: data.toString("utf8"),
    };
    return;
  }

  await withSftp(server, async (client) => {
    await client.put(data, path);
  });
}

/**
 * `mkdir -p`: create `path` and any missing parents; a no-op when it already
 * exists as a directory. Used by folder uploads. Callers pass an already
 * validated absolute path.
 */
export async function mkdirpPath(server: SftpServer, path: string): Promise<void> {
  if (SANDBOX) {
    let cur = "";
    for (const seg of splitPath(path)) {
      cur += "/" + seg;
      const node = simResolve(server.id, cur);
      if (node) {
        if (node.type !== "dir") throw new Error("A file with that name already exists.");
        continue;
      }
      const loc = simParent(server.id, cur);
      if (!loc) throw new Error("Invalid path.");
      loc.parent.children[loc.name] = { type: "dir", mtime: Date.now(), mode: 0o755, children: {} };
    }
    return;
  }

  await withSftp(server, async (client) => {
    // ssh2-sftp-client's recursive mkdir stats each level and only creates
    // what is missing; it rejects if a level exists as a non-directory.
    await client.mkdir(path, true);
  });
}

