 * On success returns the new job's id so the hero's power controls
 * (components/customer/power/usePowerGuard.ts) can follow that exact job to
 * completion rather than re-enabling on a timer.
 */
export async function gamePower(
  serverId: string,
  action: string,
): Promise<{ ok: true; jobId: string } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedServer(serverId);
    requireSpec(server);
    if (!isPowerAction(action)) return { ok: false, error: "Unsupported action." };
    const limited = throttle(user.id, "power", 20);
    if (limited) return { ok: false, error: limited };
    if (server.status !== "RUNNING")
      return { ok: false, error: "The VM must be running to control the game service." };

    // Check-then-enqueue under the per-server advisory lock (lib/job-guard.ts).
    // As two separate reads followed by a create, 10 simultaneous Restart
    // requests against one staging server enqueued 2 GAME_POWER jobs.
    const queued = await withServerJobLock(server.id, async (tx): Promise<{ jobId: string } | { busy: string }> => {
      if (await lifecycleBusy(server.id, tx)) return { busy: "Another server operation is in progress — try again shortly." };
      if (await gameJobInflight(server.id, tx)) return { busy: "A game control action is already in progress on this server." };
      // A slow-booting game is already coming up: a repeat Start/Restart would only
      // restart it again and push readiness back out (lib/game-power-start.ts).
      if (action !== "stop") {
        const rt = await tx.gameRuntime.findUnique({ where: { serverId: server.id }, select: { state: true, probedAt: true, startedAt: true } });
        if (startingBlocksRestart(rt, new Date()))
          return { busy: "The game is still starting up — give it a few minutes; restarting now would only slow it down." };
      }
      const job = await tx.job.create({
        data: {
          type: "GAME_POWER",
          serverId: server.id,
          // `source`/`by` become the recorded run intent (worker/game-control.ts),
          // which is how "stopped by you" is told apart from "crashed".
          payload: {
            action,
            announce: action === "restart",
            source: server.userId === user.id ? "customer" : "admin",
            by: user.id,
          },
        },
        select: { id: true },
      });
      return { jobId: job.id };
    });
    if ("busy" in queued) return { ok: false, error: queued.busy };

    await db.auditLog.create({
      data: { userId: user.id, action: "gameserver.power", detail: `${action} on ${server.hostname}` },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true, jobId: queued.jobId };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

