export function pinnedVersion(config: unknown): string | null {
  const cfg = (config ?? null) as Record<string, unknown> | null;
  const raw = cfg && typeof cfg.VERSION === "string" ? cfg.VERSION.trim() : "";
  return raw && !/^(latest|snapshot|stable|experimental)$/i.test(raw) && /^[0-9A-Za-z.\-+_]{1,40}$/.test(raw) ? raw : null;
}

