  if (!job.serverId) throw new Error("game power: missing serverId");
  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
  if (!server) throw new Error(`Server ${job.serverId} not found`);
