  // what lets the dashboard and the fleet sweep tell "stopped by choice" from
  // "crashed". Only the first attempt of a job records (a retry is not a new ask).
  const intent = intentForPowerAction(action);
  if (intent && job.attempts <= 1) await recordIntent(server.id, intent, p.source ?? "customer", p.by ?? null);

  if (SANDBOX) {
    await notify(
      server.userId,
      `Game service ${action} (sandbox) on ${server.hostname}`,
      `Sandbox only — no VM was contacted; the ${spec.label} service was not ${action}ed.`,
      href
    );
    return;
  }
  if (server.status !== "RUNNING") throw new Error("game power: VM is not running");

  // Optional pre-restart announce over RCON (best-effort; never fails the action).
  if (action === "restart" && p.announce && spec.rcon === "source") {
    try {
      await withServerSsh(server as SftpServer, (conn) =>
        runRcon(conn, spec, "say Server is restarting now (scheduled/maintenance).")
      );
    } catch (e) {
      console.error("[game-control] restart announce failed (continuing)", e);
    }
  }

