import type { MetadataRoute } from "next";
import { notFound } from "next/navigation";
import { isKnownSection, listSections, sectionEntries } from "@/lib/sitemap-sections";

export const dynamic = "force-dynamic";

/**
 * One sitemap file per SECTION (core, games, game-locations, locations,
 * compare, blog, tools, servers, mods-1..N), served at /sitemap/<id>.xml and
 * indexed by the hand-written <sitemapindex> at /sitemap.xml
 * (app/sitemap.xml/route.ts — Next does not build an index when
 * generateSitemaps() is present). All the section/lastmod/priority policy lives
 * in lib/sitemap-sections.ts; mod chunking in lib/sitemap-mods.ts.
 */
export async function generateSitemaps(): Promise<Array<{ id: string }>> {
  return (await listSections()).map((s) => ({ id: s.id }));
}

export default async function sitemap({ id }: { id?: string | number } = {}): Promise<MetadataRoute.Sitemap> {
  const sid = String(id ?? "core");
  // Only the ids the index lists exist: the retired numeric chunks (/sitemap/0.xml ...) used to answer an
  // empty 200 <urlset>, which Search Console reports as a broken sitemap instead of a gone one.
  if (!(await isKnownSection(sid))) notFound();
  const entries = await sectionEntries(sid);
  return entries.map((e) => ({ url: e.url, ...(e.lastModified ? { lastModified: e.lastModified } : {}) }));
}
