import type { MetadataRoute } from "next";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

// Note: /riddle/chamber-of-echoes is GATE 2 of the Nxeon Cipher promo — the one
// disallowed path that isn't infra. Seekers who "read what the crawlers must
// not" find the hidden chamber here.
const DISALLOW = ["/dashboard", "/admin", "/api", "/login", "/register", "/forgot-password", "/reset-password", "/riddle/chamber-of-echoes"];

/**
 * Answer-engine crawlers are named explicitly. A crawler that matches a named
 * group ignores the `*` group entirely, so each group repeats the disallow
 * list. ChatGPT is the site's #1 acquisition channel; OAI-SearchBot (search
 * index) and ChatGPT-User (live browsing on behalf of a user) are what let it
 * cite pages, so they are always allowed. GPTBot (model training) is allowed
 * too — flip AI_TRAINING_CRAWLERS=0 to block the training-only agents without
 * touching search/citation access.
 */
const AI_SEARCH_AGENTS = ["OAI-SearchBot", "ChatGPT-User", "PerplexityBot", "Perplexity-User", "Claude-SearchBot", "Claude-User", "DuckAssistBot", "Applebot"];
const AI_TRAINING_AGENTS = ["GPTBot", "ClaudeBot", "Google-Extended", "Applebot-Extended", "CCBot"];

export default function robots(): MetadataRoute.Robots {
  const training = process.env.AI_TRAINING_CRAWLERS !== "0";
  return {
    rules: [
      { userAgent: "*", allow: "/", disallow: DISALLOW },
      { userAgent: AI_SEARCH_AGENTS, allow: "/", disallow: DISALLOW },
      training ? { userAgent: AI_TRAINING_AGENTS, allow: "/", disallow: DISALLOW } : { userAgent: AI_TRAINING_AGENTS, disallow: "/" },
    ],
    sitemap: `${APP_URL}/sitemap.xml`,
    host: APP_URL,
