/**
 * The ONE switch for customer/public dedicated-server surfaces.
 *
 * Every customer route (app/(marketing)/dedicated-servers, app/dashboard/dedicated/**)
 * calls `requireDedicatedPublic()` first: while Setting dedicated_public_enabled is
 * off it is a plain 404, exactly as if the route did not exist. Admin previews
 * (app/admin/preview/dedicated/**) do NOT use this gate — they are admin-only
 * and render the same components with `preview` set.
 *
 * test/dedicated-gate.test.ts asserts every customer route file calls this, and
 * that no sitemap section / customer nav lists the routes while the flag is off.
 */
import { notFound } from "next/navigation";
import { getSettingBool } from "../settings";

export const DEDICATED_PUBLIC_FLAG = "dedicated_public_enabled";
export const DEDICATED_PUBLIC_PATH = "/dedicated-servers";
export const DEDICATED_DASHBOARD_PATH = "/dashboard/dedicated";

/** Pure decision (unit-tested): render, or 404. */
export function dedicatedRouteDecision(flagOn: boolean): "render" | "not-found" {
  return flagOn ? "render" : "not-found";
}

export async function dedicatedPublicEnabled(): Promise<boolean> {
  try {
    return await getSettingBool(DEDICATED_PUBLIC_FLAG, false);
  } catch {
    return false; // fail CLOSED: a DB hiccup must never expose an unreleased page
  }
}

export async function requireDedicatedPublic(): Promise<void> {
  if (dedicatedRouteDecision(await dedicatedPublicEnabled()) === "not-found") notFound();
}

/** Sitemap paths contributed by this feature (empty while the flag is off). */
export function dedicatedSitemapPaths(flagOn: boolean): string[] {
  return flagOn ? [DEDICATED_PUBLIC_PATH] : [];
}
