/**
 * Pure policy for the OVH admin controls: who counts as the OWNER, and the
 * single-use, short-lived challenge that guards node reboot / rescue boot.
 *
 * OWNER: the platform has no separate owner role (one ADMIN account today), so
 *  - if NXEON_OWNER_EMAILS is set (comma-separated), only those ADMIN emails;
 *  - otherwise the ADMIN account counts as owner ONLY while it is the sole
 *    ADMIN. A second ADMIN appearing makes owner-only controls fail closed
 *    until the env var names the owner explicitly.
 *
 * CHALLENGE (reboot / rescue): an action cannot be executed from one click or
 * from a stale page. `prepare` snapshots the node's customer-VM list and
 * returns a nonce; `execute` must present that nonce (single-use, 5-minute
 * TTL, bound to the same admin + node + action), the node's exact name typed,
 * and the VM count it was shown. If any VM was added/removed since the warning
 * was rendered the fingerprint differs and execution is refused.
 */
import { createHash, randomBytes } from "node:crypto";

export function parseOwnerEmails(raw: string | undefined | null): string[] {
  return (raw ?? "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter((s) => s.includes("@"));
}

export function isOwner(user: { role: string; email: string }, ownerEmails: readonly string[], adminCount: number): { ok: true } | { ok: false; error: string } {
  if (user.role !== "ADMIN") return { ok: false, error: "Owner only." };
  if (ownerEmails.length > 0) {
    return ownerEmails.includes(user.email.toLowerCase()) ? { ok: true } : { ok: false, error: "Owner only (not listed in NXEON_OWNER_EMAILS)." };
  }
  if (adminCount === 1) return { ok: true };
  return { ok: false, error: "Owner only: more than one ADMIN exists, so set NXEON_OWNER_EMAILS to name the owner." };
}

export type PowerAction = "reboot" | "rescue_on" | "rescue_off" | "rescue_on_reboot" | "rescue_off_reboot";
export const POWER_ACTIONS: PowerAction[] = ["reboot", "rescue_on", "rescue_off", "rescue_on_reboot", "rescue_off_reboot"];

export function powerActionLabel(a: PowerAction): string {
  return {
